import json
import math
import os
import re
import sys
from datetime import datetime, timezone

QUANTITIES = ["temp", "rh", "pres", "wspd", "wdir", "rain"]
RANGES = {"temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
          "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000)}
DIRECTIVE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")
MISSING_ZERO = re.compile(r"^-9999(\.0*)?$")


def epoch(text):
    text = text.strip().replace("T", " ").rstrip("Z")
    parsed = datetime.strptime(text, "%Y-%m-%d %H:%M:%S")
    return int(parsed.replace(tzinfo=timezone.utc).timestamp())


def parse_tz(text):
    text = text.strip()
    if text == "Z":
        return 0
    sign = -1 if text[0] == "-" else 1
    hours, minutes = text[1:].split(":")
    return sign * (int(hours) * 3600 + int(minutes) * 60)


def convert(quantity, unit, value):
    if quantity == "temp":
        if unit == "degF":
            return (value - 32) * 5 / 9
        if unit == "K":
            return value - 273.15
    elif quantity == "rh":
        if unit == "frac":
            return value * 100
    elif quantity == "pres":
        if unit == "kPa":
            return value * 10
        if unit == "inHg":
            return value * 33.8638866667
        if unit == "mmHg":
            return value * 1.33322387415
    elif quantity == "wspd":
        if unit == "kmh":
            return value / 3.6
        if unit == "kn":
            return value * 1852 / 3600
        if unit == "mph":
            return value * 0.44704
    elif quantity == "rain":
        if unit.startswith("tips:"):
            return value * float(unit[5:])
    return value


def parse_value(field):
    field = field.strip()
    if field == "" or field == "---" or field.lower() == "nan" or MISSING_ZERO.match(field):
        return None
    try:
        return float(field)
    except ValueError:
        return None


def read_file(path):
    with open(path, "rb") as handle:
        text = handle.read().decode("utf-8")
    if text.startswith("\ufeff"):
        text = text[1:]
    header = {}
    columns = []
    units = {}
    rows = []
    syncs = []
    for line in text.splitlines():
        if not line.strip():
            continue
        if line.startswith("#"):
            match = DIRECTIVE.match(line)
            if not match:
                continue
            key, value = match.group(1), match.group(2).strip()
            if key in ("station", "upload", "interval", "tz"):
                header[key] = value
            elif key == "columns":
                columns = [name.strip() for name in value.split(",")]
            elif key == "units":
                for pair in value.split():
                    if "=" in pair:
                        name, unit = pair.split("=", 1)
                        units[name] = unit
            elif key == "sync":
                parts = {}
                for part in value.split():
                    if "=" in part:
                        name, content = part.split("=", 1)
                        parts[name] = content
                if "logger" in parts and "ref" in parts:
                    syncs.append((epoch(parts["logger"]), epoch(parts["ref"])))
            continue
        fields = line.split(",")
        row = {}
        for name, field in zip(columns, fields):
            if name == "time":
                row["time"] = epoch(field)
                continue
            value = parse_value(field)
            if value is not None:
                value = convert(name, units.get(name, "canonical"), value)
                low, high = RANGES.get(name, (-math.inf, math.inf))
                if not (low <= value <= high):
                    value = None
            row[name] = value
        rows.append(row)
    return header, rows, syncs


def floor_hour_end(instant):
    return -((-instant) // 3600) * 3600


def main():
    input_dir, output_file = sys.argv[1], sys.argv[2]
    stations = {}
    for name in sorted(os.listdir(input_dir)):
        path = os.path.join(input_dir, name)
        if not name.endswith(".log") or not os.path.isfile(path):
            continue
        header, rows, syncs = read_file(path)
        if not rows:
            continue
        station = header["station"]
        offset = parse_tz(header["tz"])
        upload = int(header["upload"])
        info = stations.setdefault(station, {"interval": 0, "samples": {}, "syncs": {}})
        info["interval"] = int(float(header["interval"]))
        for logger, ref in syncs:
            instant = logger - offset
            known = info["syncs"].get(instant)
            if known is None or upload > known[0]:
                info["syncs"][instant] = (upload, ref - instant)
        for row in rows:
            instant = row["time"] - offset
            known = info["samples"].get(instant)
            if known is None or upload > known[0]:
                info["samples"][instant] = (upload, row)
        for logger, ref in syncs:
            pass

    result = []
    for station in sorted(stations):
        info = stations[station]
        interval = info["interval"]
        points = sorted((t, o[1]) for t, o in info["syncs"].items())

        def clock_offset(instant):
            if not points:
                return 0
            if instant <= points[0][0]:
                return points[0][1]
            if instant >= points[-1][0]:
                return points[-1][1]
            for index in range(1, len(points)):
                t2, o2 = points[index]
                if instant <= t2:
                    t1, o1 = points[index - 1]
                    span = t2 - t1
                    return (o1 * span + (o2 - o1) * (instant - t1)) // span
            return points[-1][1]

        samples = []
        for instant, (_, row) in info["samples"].items():
            samples.append((instant + clock_offset(instant), row))
        samples.sort(key=lambda item: item[0])
        first = floor_hour_end(samples[0][0])
        last = floor_hour_end(samples[-1][0])
        buckets = {}
        for corrected, row in samples:
            buckets.setdefault(floor_hour_end(corrected), []).append((corrected, row))

        increments = {}
        previous = None
        for corrected, row in samples:
            value = row.get("rain")
            if value is None:
                continue
            if previous is not None and (corrected - previous[0]) * 2 <= 5 * interval:
                p = previous[1]
                increments[id(row)] = value - p if value >= p else value
            previous = (corrected, value)

        expected = 3600 / interval
        hours = []
        for hour in range(first, last + 1, 3600):
            entries = buckets.get(hour, [])
            entry = {"hour": datetime.fromtimestamp(hour, timezone.utc).strftime("%Y-%m-%dT%H:00:00Z")}
            for quantity in QUANTITIES:
                readings = [row for _, row in entries if row.get(quantity) is not None]
                count = len(readings)
                value = None
                if count * 4 >= expected * 3 and count > 0:
                    if quantity in ("temp", "rh", "pres", "wspd"):
                        value = sum(row[quantity] for row in readings) / count
                    elif quantity == "rain":
                        value = sum(increments.get(id(row), 0) for row in readings)
                    else:
                        east = north = 0.0
                        vectors = 0
                        for row in readings:
                            speed = row.get("wspd")
                            if speed is not None and speed > 0:
                                angle = math.radians(row["wdir"])
                                east += math.sin(angle)
                                north += math.cos(angle)
                                vectors += 1
                        if vectors:
                            value = math.degrees(math.atan2(east, north)) % 360
                    if value is not None:
                        value = round(value, 2)
                        if quantity == "wdir" and value >= 360:
                            value = 0.0
                        value = value + 0.0
                entry[quantity] = {"value": value, "n": count}
            hours.append(entry)
        result.append({"station": station, "interval_s": interval, "hours": hours})

    with open(output_file, "w") as handle:
        json.dump({"stations": result}, handle, indent=1)


main()
